INSERT INTO "calc_syntax_rules" ("key", "value_json") VALUES ('caseSensitive', '{"functionNames": false}');
INSERT INTO "calc_syntax_rules" ("key", "value_json") VALUES ('fieldReference', '"Table::Field"');
